import { httpServerHandler } from 'cloudflare:node';

// Inject Cloudflare env bindings into process.env before loading Express app
let initialized = false;

function initEnv(env) {
  if (!initialized && env) {
    for (const [key, value] of Object.entries(env)) {
      if (typeof value === 'string') {
        process.env[key] = value;
      }
    }
    initialized = true;
  }
}

// Lazy-load Express app so env vars are available when modules read process.env
let app;
function getApp() {
  if (!app) {
    app = require('./server');
  }
  return app;
}

// Use Cloudflare's native httpServerHandler for Express compatibility
const expressHandler = httpServerHandler({ port: 8787 });

export default {
  async fetch(request, env, ctx) {
    try {
      initEnv(env);
      getApp().listen(8787);
      return expressHandler.fetch(request, env, ctx);
    } catch (err) {
      return new Response(
        JSON.stringify({ success: false, error: err.message, stack: err.stack }),
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }
  }
};

